            return;
        }

        double min_diff = 1e9;
        long ans_num = 0;
        long ans_den = 1;

        for (long i = 1; i <= m; i++) {
            long g = gcd(i, b);
            long h = a * i / g;
            long w = a * (h / b);

            double diff1 = (double)(w - ((w / (h / i)) * (h / i))) / (double)h;
            if (min_diff > diff1) {
                min_diff = diff1;
                ans_num = (w / (h / i));
                ans_den = i;
            }

            long numerator = w + (h / i) - 1;
            long denominator = (h / i);
            double diff2 = Math.abs(w - ((numerator / denominator) * denominator)) / (double)h;
            if (min_diff > diff2) {
                min_diff = diff2;
                ans_num = (numerator / denominator);
                ans_den = i;
            }
        }

        long g = gcd(ans_num, ans_den);
        ans_num /= g;
        ans_den /= g;

        System.out.println(ans_num + "/" + ans_den);
    }

    private static long gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
